```java
public class Stack {
    private int[] data;
    private int count;

    public Stack(int capacity) {
        data = new int[capacity];
        count = 0;
    }

    public void push(int item) {
        if (count == data.length) {
            throw new IllegalStateException("Stack overflow");
        }
        data[count] = item;
        count++;
    }

    public int pop() {
        if (count == 0) {
            throw new IllegalStateException("Stack underflow");
        }
        count--;
        return data[count];
    }
}
```

